export async function profileRenderStages(renderer,game,{frames=100,input={moveX:.3,moveY:.2,shoot:true,fireMode:'manual',aimX:1400,aimY:930},onYield=()=>new Promise(requestAnimationFrame)}={}){
 const undo=[],samples=[];let current=null;
 const wrap=(object,key,label)=>{if(!object||typeof object[key]!=='function')return;const original=object[key],own=Object.hasOwn(object,key);object[key]=function(...args){const start=performance.now();try{return original.apply(this,args);}finally{if(current){const entry=current[label]??={ms:0,calls:0};entry.ms+=performance.now()-start;entry.calls++;}}};undo.push(()=>{if(own)object[key]=original;else delete object[key];});};
 const hero=renderer.livePlayer,enemies=renderer.liveEnemies;
 wrap(enemies?.batchInk,'prepare','enemies.batchInkPrepare');wrap(enemies?.batchInk,'draw','enemies.batchInkCell');
 wrap(hero?.alphaReadback,'read','hero.directRead');wrap(hero,'frame','hero.total');wrap(hero?.renderer,'render','hero.glSubmit');wrap(hero?.bodyContext,'drawImage','hero.bodyCopy');wrap(hero?.bodyContext,'getImageData','hero.bodyRead');wrap(hero?.inkContext,'drawImage','hero.inkCopy');wrap(hero?.context,'drawImage','hero.outputCopies');
 for(const m of hero?.models?.values()||[]){wrap(m.sampler,'sample','hero.clipSample');wrap(m.sampler,'updateSkinPose','hero.skinMatrices');}
 wrap(enemies?.alphaReadback,'read','enemies.directRead');wrap(enemies,'frame','enemies.poseAndSubmit');wrap(enemies,'gpuSurface','enemies.gpuCopy');wrap(enemies?.renderer,'render','enemies.glSubmit');wrap(enemies?.renderer,'setSize','enemies.resize');wrap(enemies?.rawContext,'drawImage','enemies.atlasCopy');wrap(enemies?.rawContext,'getImageData','enemies.atlasRead');wrap(enemies,'finishFrame','enemies.cellComposite');
 for(const m of enemies?.models?.values()||[]){wrap(m.sampler,'sample','enemies.clipSample');wrap(m.sampler,'updateSkinPose','enemies.skinMatrices');wrap(m.poseBounds,'project','enemies.geometryBounds');}
 wrap(renderer,'nativeEnvironmentEntry','world.propRules');wrap(renderer.productionArt,'propFrame','world.propSelection');wrap(renderer,'drawObstacle','world.props');wrap(renderer,'drawEnemy','world.enemyDraw');wrap(renderer,'drawPlayer','world.playerDraw');
 try{for(let frame=0;frame<frames;frame++){if(game.state==='upgrade')game.chooseUpgrade(game.choices[0].id);if(game.state!=='playing')break;game.tick(1/60,input);game.drainEvents();current={};const start=performance.now();renderer.render(game,{},game.time);const total=performance.now()-start;if(frame>=10)samples.push({total,stages:current});current=null;if(frame%8===0)await onYield();}}
 finally{current=null;for(const restore of undo.reverse())restore();}
 const percentile=(values,p)=>values.sort((a,b)=>a-b)[Math.floor(values.length*p)]??0,labels=[...new Set(samples.flatMap(s=>Object.keys(s.stages)))];
 const before=JSON.stringify(game.snapshot());renderer.render(game,{},game.time);
 return {frames:samples.length,total:{medianMs:percentile(samples.map(s=>s.total),.5),p95Ms:percentile(samples.map(s=>s.total),.95)},stages:labels.map(label=>({label,medianFrameMs:percentile(samples.map(s=>s.stages[label]?.ms||0),.5),p95FrameMs:percentile(samples.map(s=>s.stages[label]?.ms||0),.95),meanCallsPerFrame:samples.reduce((n,s)=>n+(s.stages[label]?.calls||0),0)/samples.length})).sort((a,b)=>b.medianFrameMs-a.medianFrameMs),identicalSnapshot:before===JSON.stringify(game.snapshot()),note:'Instrumented call wall time, not actual GPU execution or FPS. Nested categories overlap and cannot be summed.',samples};
}
